  Transaction(coinName: 'A', timestamp: DateTime(2022, 1, 1), profitOrLoss: 5),
  Transaction(coinName: 'B', timestamp: DateTime(2022, 1, 2), profitOrLoss: 10),
  Transaction(coinName: 'C', timestamp: DateTime(2022, 1, 3), profitOrLoss: 2),
  Transaction(coinName: 'A', timestamp: DateTime(2022, 1, 4), profitOrLoss: -3),
  Transaction(coinName: 'B', timestamp: DateTime(2022, 1, 5), profitOrLoss: -6),
  Transaction(coinName: 'C', timestamp: DateTime(2022, 1, 6), profitOrLoss: -8),
];

void main() {
  List<String> topProfitCoins = getTopProfitCoins(transactions);
  List<String> topLossCoins = getTopLossCoins(transactions);
  print('Top Profit Coins: $topProfitCoins');
  print('Top Loss Coins: $topLossCoins');
}

List<String> getTopProfitCoins(List<Transaction> transactions) {
  List<String> topProfitCoins = [];
  Map<String, int> profitByCoin = {};

  for (Transaction transaction in transactions) {
    if (!profitByCoin.containsKey(transaction.coinName)) {
      profitByCoin[transaction.coinName] = transaction.profitOrLoss;
    } else {
      profitByCoin[transaction.coinName] += transaction.profitOrLoss;
    }
  }

  List<MapEntry<String, int>> sortedProfits = profitByCoin.entries.toList()..sort((a, b) => b.value.compareTo(a.value));

  for (int i = 0; i < 3; i++) {
    topProfitCoins.add(sortedProfits[i].key);
  }

  return topProfitCoins;
}

List<String> getTopLossCoins(List<Transaction> transactions) {
  List<String> topLossCoins = [];
  Map<String, int> lossByCoin = {};

  for (Transaction transaction in transactions) {
    if (!lossByCoin.containsKey(transaction.coinName)) {
      lossByCoin[transaction.coinName] = transaction.profitOrLoss;
    } else {
      lossByCoin[transaction.coinName] += transaction.profitOrLoss;
    }
  }

  List<MapEntry<String, int>> sortedLosses = lossByCoin.entries.toList()..sort((a, b) => a.value.compareTo(b.value));

  for (int i = 0; i < 3; i++) {
    topLossCoins.add(sortedLosses[i].key);
  }

  return topLossCoins;
}
```

