List<String> getTopCoinsWithHighestAverageProfit(List<Transaction> transactions) {
  double avgProfit = 0;
  List<String> topCoins = [];

  for (Transaction transaction in transactions) {
    avgProfit += transaction.profitEarned;
  }

  avgProfit /= transactions.length;

  for (Transaction transaction in transactions) {
    if (transaction.profitEarned > avgProfit) {
      topCoins.add(transaction.coinName);
