using UnityEngine;

public class AudioVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public Graphics graphics;
    public int sampleCount = 1024;
    public float sampleRate = 44100;
    public float timeOffset = 0.0f;

    private float[] samples;
    private float[] vertices;

    private Coroutine visualizerCoroutine;

    void Start()
    {
        samples = new float[sampleCount];
        vertices = new float[sampleCount * 2];

        visualizerCoroutine = StartCoroutine(VisualizerCoroutine());
    }

    IEnumerator VisualizerCoroutine()
    {
        while (true)
        {
            audioSource.GetSamples(samples, 0, sampleCount);

            for (int i = 0; i < sampleCount; i++)
            {
                vertices[i * 2] = samples[i];
                vertices[i * 2 + 1] = 0.0f;
            }

            graphics.SetVertices(vertices);

            timeOffset += Time.deltaTime;
            samples = new float[sampleCount];

            yield return null;
        }
    }
