interface Email {
  email: string;
}

interface Props {
  onSelect: (email: Email) => void;
}

const EmailInput: React.FC<Props> = ({ onSelect }) => {
  const dispatch = useDispatch<AppDispatch>();
  const { emails } = useSelector((state: RootState) => state.email);

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    highlightedIndex,
  } = useCombobox({
    items: emails,
    getItemPredicate: (item: Email, query: string) =>
      item.email.toLowerCase().startsWith(query.toLowerCase()),
  });

  const handleSelect = useCallback(
    (item: Email) => {
      onSelect(item);
      setSelectedItem(null);
    },
    [onSelect]
  );

  const handleInputChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const prefix = event.target.value;
      dispatch(fetchEmails(prefix));
    },
    [dispatch]
  );

  useEffect(() => {
    if (selectedItem) {
      setSelectedItem(null);
    }
  }, [selectedItem]);

