  const [editedName, setEditedName] = useState("");
  const [editedPrompt, setEditedPrompt] = useState("");

  const { isOpen, onOpen, onClose } = useDisclosure();

  const promptsQuery = api.prompt.all.useQuery();
  const upsertPromptMutation = useMutation({
    onSuccess: () => utils.prompt.invalidate(),
  });
  const deletePromptMutation = useMutation({
    onSuccess: () => utils.prompt.invalidate(),
  });

  const handleEditPrompt = useCallback((promptId, newName, newPrompt) => {
    setSelectedTargetPrompt(promptId);
    setEditedName(newName);
    setEditedPrompt(newPrompt);
    onOpen();
  }, []);

  const handleDeletePrompt = useCallback((promptId) => {
    setSelectedTargetPrompt(promptId);
    onOpen();
  }, []);

  const handleSavePrompt = useCallback((promptId, newName, newPrompt) => {
    upsertPromptMutation.mutate({ id: promptId, name: newName, prompt: newPrompt });
    onClose();
  }, [upsertPromptMutation]);

  const handleClosePrompt = useCallback(() => {
    setSelectedTargetPrompt("");
    setEditedName("");
    setEditedPrompt("");
    onClose();
  }, []);

  const optimizedPrompts = useMemo(() => {
    if (!promptsQuery.data) {
      return [];
    }

    return promptsQuery.data
      .sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime())
      .map((p) => ({
        id: p.id,
        name: p.name,
        prompt: p.prompt,
      }));
  }, [promptsQuery.data]);

  return (
