            var tokenizer = new WordTokenizer();
            var stopWords = new[] { "a", "an", "the", "and", "or", "but", "if", "or", "because", "as", "until", "while", "of", "to", "from", "at", "by", "for", "with", "about", "against", "below", "to", "from", "up", "in", "out", "during", "after", "above", "again", "further", "then", "once", "here", "there", "when", "where", "why", "how", "all", "any", "both", "each", "few", "more", "most", "other", "some", "such", "no", "nor", "not", "only", "so", "too", "very", "can", "will", "just", "don", "should", "now" };
            var preprocessor = new TextPreprocessor(tokenizer, stopWords);

            // Create a NaiveBayes classifier
            var naiveBayes = new NaiveBayes();

            // Fit the model on the labeled dataset
            var transformedDataset = dataset.Select(x => (x.Item1, preprocessor.Transform(x.Item2)));
            var matrix = new CountMatrix(transformedDataset);
            naiveBayes.Learn(matrix);

            // Predict the labels of new observations
